mapper.select:
        select
        subscribes.*,
        beautyProjects.title,
        beautyProjects.info,
        beautyProjects.cover_img,
        beautyProjects.price,
        user.nick_name,
        user.avatar,
        user.tel
        from subscribes subscribes
        left join beauty_projects beautyProjects on subscribes.project_id = beautyProjects.id
		left join user user on subscribes.user_id = user.id

            and subscribes.id = #{id}
            and subscribes.bid = #{bid}
            and subscribes.project_id = #{projectId}
            and subscribes.user_id = #{userId}
            and subscribes.start_time = #{startTime}
            and subscribes.create_time = #{createTime}
            and subscribes.status = #{status}
            and beautyProjects.title like concat('%',#{title},'%')
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}
            and user.tel = #{tel}

		order by subscribes.id desc

            limit #{current},#{pageSize}

        select count(*) from subscribes subscribes
        left join beauty_projects beautyProjects on subscribes.project_id = beautyProjects.id
		left join user user on subscribes.user_id = user.id

            and subscribes.id = #{id}
            and subscribes.bid = #{bid}
            and subscribes.project_id = #{projectId}
            and subscribes.user_id = #{userId}
            and subscribes.start_time = #{startTime}
            and subscribes.create_time = #{createTime}
            and subscribes.status = #{status}
            and beautyProjects.title like concat('%',#{title},'%')
            and user.nick_name like concat('%',#{nickName},'%')
            and user.avatar = #{avatar}
            and user.tel = #{tel}
